 if(flow&&!paused.value){const pos=flow.geometry.getAttribute('position') as THREE.BufferAttribute;for(let i=0;i<flows.length;i++){const p=flows[i];curves.get(p.edgeId)!.getPoint((p.phase+time*p.speed)%1,scratch);pos.setXYZ(i,scratch.x,scratch.y,scratch.z)}pos.needsUpdate=true}
