 renderer=new THREE.WebGLRenderer({antialias:true,alpha:false,powerPreference:'high-performance'});renderer.setPixelRatio(Math.min(devicePixelRatio,innerWidth>700?1.5:1.1));renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.05;renderer.domElement.setAttribute('aria-label','三维印学知识图谱，可拖动旋转、滚轮缩放、点击节点和连线查看资料');renderer.domElement.setAttribute('role','img');el.appendChild(renderer.domElement)
